ALTER TABLE persona_voice_profile ADD COLUMN IF NOT EXISTS tts_lang TEXT; INSERT INTO persona_voice_profile (persona_key, tts_voice_id, tts_rate, tts_pitch, tts_lang) VALUES ('Kabbalah_prompt-3_v16','ru_male_wise_low',0.92,-0.15,'ru-RU') ON CONFLICT (persona_key) DO UPDATE SET tts_voice_id=EXCLUDED.tts_voice_id, tts_rate=EXCLUDED.tts_rate, tts_pitch=EXCLUDED.tts_pitch, tts_lang=EXCLUDED.tts_lang, updated_at=NOW(); SELECT persona_key, tts_voice_id, tts_rate, tts_pitch, COALESCE(tts_lang,'ru-RU') AS tts_lang FROM persona_voice_profile WHERE persona_key='Kabbalah_prompt-3_v16';
